<script setup lang="ts">
import {ref,onMounted,nextTick,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import {SlidersHorizontal,ShieldCheck,BookOpen,Sparkles,Check,ArrowUpRight,Trash2,AlertTriangle,X} from 'lucide-vue-next'
import {post,safeUrl} from '../api'
import {useApp} from '../stores/app'
import type {Depth} from '../types'
const app=useApp(),router=useRouter(),familiar=ref<string[]>([]),depth=ref<Depth>('beginner'),intensity=ref(.65),timezone=ref('Asia/Shanghai'),broadHistory=ref(true),saving=ref(false),error=ref(''),saved=ref(false),resetOpen=ref(false),confirmText=ref(''),resetting=ref(false),resetError=ref(''),modal=ref<HTMLElement|null>(null)
const sections=[{id:'preferences',icon:SlidersHorizontal,name:'探索偏好'},{id:'ai',icon:Sparkles,name:'AI 导师'},{id:'privacy',icon:ShieldCheck,name:'隐私与数据'},{id:'sources',icon:BookOpen,name:'来源与透明性'}]
onMounted(()=>{const p=app.profile;if(p){familiar.value=[...p.familiar_disciplines];depth.value=p.depth;intensity.value=p.intensity;timezone.value=p.timezone;broadHistory.value=p.broad_use_history}})
function toggle(id:string){familiar.value=familiar.value.includes(id)?familiar.value.filter(x=>x!==id):[...familiar.value,id];saved.value=false}
async function save(){saving.value=true;error.value='';saved.value=false;try{await app.update({familiar_disciplines:familiar.value,depth:depth.value,intensity:Number(intensity.value),timezone:timezone.value,broad_use_history:broadHistory.value,onboarding_complete:true});saved.value=true;app.notify('偏好已保存；新批次将使用这些设置。')}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
function trap(e:KeyboardEvent){if(e.key==='Escape'&&!resetting.value){closeReset();return}if(e.key!=='Tab')return;const nodes=modal.value?.querySelectorAll<HTMLElement>('button,input');if(!nodes?.length)return;const first=nodes[0]!,last=nodes[nodes.length-1]!;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
async function openReset(){resetOpen.value=true;confirmText.value='';resetError.value='';await nextTick();modal.value?.focus();document.addEventListener('keydown',trap)}
function closeReset(){if(resetting.value)return;resetOpen.value=false;document.removeEventListener('keydown',trap)}
async function reset(){if(confirmText.value!=='清除')return;resetting.value=true;resetError.value='';try{await post('/profile/reset',{confirm:true});await app.init();app.notify('当前档案的个人探索记录已清除。');resetOpen.value=false;document.removeEventListener('keydown',trap);await router.push('/')}catch(e){resetError.value=e instanceof Error?e.message:'清除失败'}finally{resetting.value=false}}
onBeforeUnmount(()=>document.removeEventListener('keydown',trap))
</script>
<template><div class="settings-page"><header class="page-heading"><div><p class="eyebrow">MAKE ROOM FOR CURIOSITY</p><h1>探索，由你定义<span class="serif-accent">.</span></h1><p>调整起点、理解边界，始终掌握自己的探索记录。</p></div></header><div class="settings-layout"><nav class="settings-nav" aria-label="设置章节"><a v-for="s in sections" :key="s.id" :href="`#${s.id}`"><component :is="s.icon" :size="17"/>{{s.name}}</a></nav><div class="settings-main"><section id="preferences" class="settings-section"><div class="section-heading"><SlidersHorizontal :size="21"/><h2>探索偏好</h2></div><p class="muted">这些信息帮助推荐和解释，随时可改，不会成为永久边界。</p><form @submit.prevent="save"><div class="setting-field"><p class="field-label">你熟悉的领域 <span>可多选或全部留空</span></p><div class="discipline-options"><button v-for="d in app.disciplines" :key="d.id" type="button" :class="['option-pill',{selected:familiar.includes(d.id)}]" :aria-pressed="familiar.includes(d.id)" @click="toggle(d.id)"><i :style="{background:d.color}"/>{{d.name}}</button></div></div><div class="settings-row"><div class="setting-field"><label for="depth" class="field-label">默认解释深度</label><select id="depth" v-model="depth"><option value="beginner">入门 · 一分钟看懂</option><option value="intermediate">进阶 · 连接原理与应用</option><option value="deep">深入 · 机制与开放问题</option></select></div><div class="setting-field"><label for="timezone" class="field-label">每日推荐时区</label><input id="timezone" v-model="timezone" maxlength="80" placeholder="Asia/Shanghai" required><p class="privacy-note">使用 IANA 时区，如 Asia/Shanghai。决定“今天”的日期。</p></div></div><div class="setting-field"><label for="intensity" class="field-label">探索强度 <strong>{{Number(intensity).toFixed(2)}}</strong></label><input id="intensity" type="range" min="0" max="1" step=".05" v-model="intensity"><div class="range-labels"><span>温和拓宽</span><span>走得更远</span></div><p class="privacy-note">提高强度，会增加陌生学科或细分主题的新颖度权重；质量与可学习性要求仍然保留。</p></div><div class="setting-field history-setting"><div><label for="broad-history" class="field-label">广域探索使用近期曝光记录</label><p class="muted">开启：不按兴趣排序，用近期曝光减少重复。<br>关闭：完全不使用个人历史，按学科分层与质量选取。</p></div><input id="broad-history" type="checkbox" v-model="broadHistory" role="switch" :aria-checked="broadHistory" class="toggle-input"></div><div class="save-row"><span>保存后当前批次保持稳定，点击“换一组”应用新设置。</span><button class="button primary" type="submit" :disabled="saving"><Check :size="16"/>{{saving?'正在保存…':saved?'已保存':'保存偏好'}}</button></div><p v-if="error" class="inline-error" role="alert">{{error}}</p></form></section><section id="ai" class="settings-section"><div class="section-heading"><Sparkles :size="21"/><h2>AI 知识导师</h2><span :class="['status-pill',{available:app.profile?.ai.configured}]"><i/>{{app.profile?.ai.configured?'已配置':'未配置 · 原始资料可用'}}</span></div><p>AI 用于解释资料和围绕主题讨论，推荐本身不依赖实时 AI 调用。</p><div v-if="app.profile?.ai.configured" class="configuration-info"><strong>当前模型：{{app.profile.ai.model||'服务端已配置'}}</strong><p>在主题详情中按需生成解释。超时、限流或证据校验失败时，原始资料仍然可以阅读。</p></div><div v-else class="configuration-info"><strong>在服务端配置兼容 API 后启用</strong><p>部署者可在服务端环境文件配置 Base URL、Model 和 API Key，然后重启服务。请参考项目 README 与 .env.example。浏览器不会接收或保存密钥。</p><code>LLM_BASE_URL · LLM_MODEL · LLM_API_KEY</code></div><p class="privacy-note">AI 解释会按主题、深度、语言、模型及来源版本缓存。只有明确配置价格时才估算费用。引用有效不等于事实已被完整核实。</p></section><section id="privacy" class="settings-section"><div class="section-heading"><ShieldCheck :size="21"/><h2>隐私与数据</h2></div><p>你的档案使用服务端生成的匿名身份，通过 HttpOnly Cookie 识别；前端不能指定其他人的档案。</p><div class="privacy-facts"><div><Check :size="16"/><p>不用注册，没有账号密码。第一版面向单机自托管。</p></div><div><Check :size="16"/><p>不会根据停留时间或点击，推断你真正掌握了多少知识。</p></div><div><AlertTriangle :size="16"/><p>清除浏览器 Cookie 可能导致无法继续访问原档案，目前没有跨设备同步。</p></div></div><div class="danger-zone"><div><h3>清除当前档案的探索记录</h3><p>清除行为历史、学习状态、收藏、推荐历史和私有聊天。共享知识库和非个性化解释保留。</p></div><button class="button danger outline" @click="openReset"><Trash2 :size="15"/>清除记录</button></div></section><section id="sources" class="settings-section"><div class="section-heading"><BookOpen :size="21"/><h2>来源与透明性</h2></div><p>知识来自可追溯的外部来源。主题与来源分开保存，每条主题可以对应多个来源；摘要、AI 解释和启发性类比会分别标识。</p><div class="source-platforms"><a :href="safeUrl('https://www.mediawiki.org/wiki/API:Main_page')" target="_blank" rel="noopener noreferrer"><strong>Wikipedia / MediaWiki<ArrowUpRight :size="15"/></strong><span>百科条目、摘要与跨语言关联。内容许可以具体来源为准。</span></a><a :href="safeUrl('https://www.wikidata.org/wiki/Wikidata:Data_access')" target="_blank" rel="noopener noreferrer"><strong>Wikidata<ArrowUpRight :size="15"/></strong><span>实体与有类型的关系，保留属性语义、方向和来源。</span></a><a :href="safeUrl('https://docs.openalex.org/')" target="_blank" rel="noopener noreferrer"><strong>OpenAlex<ArrowUpRight :size="15"/></strong><span>研究主题及论文元数据。元数据不代表拥有论文全文。</span></a></div><div class="honesty-note"><h3>“可能陌生”，意味着什么？</h3><p>系统根据你的自述、历史覆盖和近期曝光估计新颖度。未曝光、未探索、自述陌生与自述已理解是四种不同状态，不能互相替代。</p><p>质量评分只是来源和元数据的代理指标。我们不宣称这些指标证明内容正确，也不将多样性直接当作学习效果。</p></div><p class="privacy-note">项目代码许可与第三方数据许可独立。来源页面提供原文、许可及署名详情；离线种子库亦保留来源元数据。</p></section></div></div><Teleport to="body"><div v-if="resetOpen" class="modal-backdrop"><section ref="modal" tabindex="-1" class="modal reset-modal" role="dialog" aria-modal="true" aria-labelledby="reset-title"><button class="icon-button modal-close" @click="closeReset" :disabled="resetting" aria-label="取消清除"><X :size="20"/></button><AlertTriangle class="danger" :size="30"/><h2 id="reset-title">清除这段探索记录？</h2><p>将删除当前匿名档案的行为历史、学习状态、收藏、推荐历史、私有聊天及个性化缓存。</p><p>共享知识库与非个性化解释会保留。此操作不可撤销。</p><label for="reset-confirm" class="field-label">输入“清除”以确认</label><input id="reset-confirm" v-model="confirmText" autocomplete="off" placeholder="清除"><p v-if="resetError" class="inline-error" role="alert">{{resetError}}</p><div class="modal-actions"><button class="button outline" @click="closeReset" :disabled="resetting">保留记录</button><button class="button danger" @click="reset" :disabled="confirmText!=='清除'||resetting">{{resetting?'正在清除…':'确认清除'}}</button></div></section></div></Teleport></div></template>
